    private void btnCheckInventoryActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnCheckInventoryActionPerformed
        DefaultTableModel model = (DefaultTableModel) tblInventory.getModel();
    model.setRowCount(0); // Clear previous data

    File file = new File("inventory.txt");
    if (!file.exists()) {
        JOptionPane.showMessageDialog(this, "No inventory data found!");
        return;
    }

    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            String[] data = line.split(",");

            String product = data[0];
            int qty = Integer.parseInt(data[1]);
            int reorder = Integer.parseInt(data[2]);
            String status = (qty <= reorder) ? "RESTOCK REQUIRED" : "OK";

            model.addRow(new Object[]{product, qty, reorder, status});
        }
    } catch (IOException e) {
        JOptionPane.showMessageDialog(this, "Error reading inventory file!");
    }
    }//GEN-LAST:event_btnCheckInventoryActionPerformed

